package com.fasterxml.jackson.dataformat.xml.ser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.IOContext;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.base.GeneratorBase;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.JsonFactory;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.databind.ObjectCodec;
import com.fasterxml.jackson.dataformat.xml.XmlPrettyPrinter;
import com.fasterxml.jackson.dataformat.xml.util.DefaultXmlPrettyPrinter;
import com.fasterxml.jackson.dataformat.xml.util.StaxUtil;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import javax.xml.namespace.QName;
import javax.xml.stream.XMLStreamException;
import javax.xml.stream.XMLStreamWriter;
import org.codehaus.stax2.XMLStreamWriter2;
import org.codehaus.stax2.ri.Stax2WriterAdapter;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.isNull;
import static org.mockito.Mockito.*;

public class ToXmlGenerator_writeNumber_TriageGen0Test {

    private IOContext ioContext;
    private ObjectCodec codec;
    private XMLStreamWriter xmlStreamWriter;
    private ToXmlGenerator generator;
    private QName testQName;

    @Before
    public void setUp() {
        ioContext = mock(IOContext.class);
        codec = mock(ObjectCodec.class);
        xmlStreamWriter = mock(XMLStreamWriter.class);
        testQName = new QName("http://test.com", "testElement");

        // Using a real JsonFactory to avoid complex constructor mocking if possible, 
        // but since ToXmlGenerator is part of Jackson, we mock the dependencies.
        generator = new ToXmlGenerator(ioContext, 0, 0, codec, xmlStreamWriter);
    }

    /**
     * Tests the case where _nextName is null. 
     * handleMissingName() is called. 
     * Note: handleMissingName usually throws an exception in Jackson.
     */
    @Test(expected = RuntimeException.class)
    public void testWriteNumber_MissingName() throws Exception {
        // _nextName is null by default
        generator.writeNumber(123L);
    }

    /**
     * Tests the case where _nextIsAttribute is true.
     */
    @Test
    public void testWriteNumber_AsAttribute() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(true);

        generator.writeNumber(456L);

        verify(xmlStreamWriter).writeLongAttribute(
                isNull(), 
                eq(testQName.getNamespaceURI()), 
                eq(testQName.getLocalPart()), 
                eq(456L)
        );
    }

    /**
     * Tests the case where checkNextIsUnwrapped() is true.
     */
    @Test
    public void testWriteNumber_Unwrapped() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        generator.setNextUnwrapped(true);

        generator.writeNumber(789L);

        verify(xmlStreamWriter).writeLong(789L);
        verify(xmlStreamWriter, never()).writeStartElement(any(), any());
    }

    /**
     * Tests the case where _xmlPrettyPrinter is null (Default behavior).
     * It should write StartElement -> writeLong -> EndElement.
     */
    @Test
    public void testWriteNumber_NoPrettyPrinter() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        generator.setNextUnwrapped(false);
        generator.setPrettyPrinter(null);

        generator.writeNumber(100L);

        verify(xmlStreamWriter).writeStartElement(testQName.getNamespaceURI(), testQName.getLocalPart());
        verify(xmlStreamWriter).writeLong(100L);
        verify(xmlStreamWriter).writeEndElement();
    }

    /**
     * Tests the case where _xmlPrettyPrinter is set.
     * It should call writeLeafElement on the pretty printer.
     */
    @Test
    public void testWriteNumber_WithPrettyPrinter() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        generator.setNextUnwrapped(false);

        // We need to mock a PrettyPrinter. Since it's an abstract class or interface 
        // in Jackson, we mock it.
        PrettyPrinter mockPrettyPrinter = mock(PrettyPrinter.class);
        generator.setPrettyPrinter(mockPrettyPrinter);

        generator.writeNumber(200L);

        verify(mockPrettyPrinter).writeLeafElement(
                eq(xmlStreamWriter), 
                eq(testQName.getNamespaceURI()), 
                eq(testQName.getLocalPart()), 
                eq(200L)
        );
        verify(xmlStreamWriter, never()).writeStartElement(any(), any());
    }

    /**
     * Tests the exception handling when XMLStreamException is thrown.
     * It should be caught and rethrown via StaxUtil.throwAsGenerationException.
     */
    @Test(expected = Exception.class) 
    public void testWriteNumber_XmlStreamException() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        generator.setNextUnwrapped(true);

        // Force an exception during writeLong
        doThrow(new XMLStreamException("Stream error")).when(xmlStreamWriter).writeLong(anyLong());

        generator.writeNumber(999L);
    }
}
